\end{displaymath}
 denote the space of fibrewise Hermitian matrices
which decay exponentially along the tube.

For instance, with $\gamma $ as in $\left( \ref{eq def path in H0}\right)$,
we have $H_\ell^{-1}.\dot{H}_{\ell }=\underset{\e{-\ell \xi}}{\underbrace{H_\ell^{-1}.H_0}}. \left(\frac{\partial}{\partial\ell} \e{\ell\xi}\right)=\xi$ and
\begin{eqnarray*}
        \left( \rho _{W}\right) _{H_{\ell }}\left( \dot{H}_{\ell }\right)
        &=&\int_{W}\Phi ^{\gamma }\left( \ell \right) \wedge \omega ^{2}
        \quad= \quad2\mathbf{i}\int_{W}\func{tr}\xi.F_{H_\ell}\wedge\omega^{2}\\
        &=&2\mathbf{i}\int_{W}\func{tr}\xi.\hat{F}_{H_\ell}\:d\func{Vol}_\omega
\end{eqnarray*}
is well-defined near $H_0$, since $\xi=\func{log}H_0^{-1}H$ is bounded and $\hat{F}_{H_{\ell }}$ is integrable [\emph{Remark \ref{Rem All about H0}}].

Thus, in this setting at least, the integral is rigorously defined:
\begin{equation} \index{norm!functional!$\mathcal{N}_{W}$}
        \mathcal{N}_{W}^{\gamma}\left( H\right):=\int_{\gamma }\rho _{W}.
\end{equation}

By the same token, if we restrict attention to our family $\left\{\gamma(t)=
H_{t}\right\} \subset \mathcal{H}_{0}$ satisfying the evolution equation
\begin{equation} \left\{ 
\begin{array}{c}
H^{-1}\dfrac{\partial H}{\partial t}=-2\mathbf{i}\hat{F}_{H} \\ 
H\left( 0\right) =H_{0}
\end{array}
\right. ,  
\end{equation}
set $\mathcal{N}_{W}\left( H_{0}\right) =0$ and write for short $\Phi _{t}:=\Phi^{\gamma}(t)$, we obtain a real smooth
function
\index{norm!functional!$\mathcal{N}_{W}$} 
\begin{equation} \mathcal{N}_{W}\left( H_{T}\right) 
        =\int_{0}^{T}\left( \rho _{W}\right)_{H_{t}}
        \left(\dot{H}_{t}\right) dt
        =\int_{0}^{T}\left( 
        \int_{W}\Phi _{t}\wedge \omega^{2}\right) dt.  
\end{equation}

The curvature of the Chern connection of $H$ obeys $F_{H}=\bar{\partial}
\partial _{H}+\partial _{H}\bar{\partial}$, so
\begin{eqnarray*}
\sigma .\bar{\partial}\partial _{H}\tau &=&\sigma .F_{H}.\tau -\sigma
.\partial _{H}\bar{\partial}\tau \\
&=&\sigma .F_{H}.\tau -\partial _{H}\left( \sigma .\bar{\partial}\tau
\right) -\bar{\partial}\left( \partial _{H}\sigma .\tau \right) +\tau .\bar{
\partial}\partial _{H}\sigma ;
\end{eqnarray*}

\emph{mutatis mutandis}, 
\begin{equation*}
\tau \bar{\partial}\partial _{H}\sigma =\tau .F_{H}.\sigma -\partial
_{H}\left( \tau .\bar{\partial}\sigma \right) -\bar{\partial}\left( \partial
_{H}\tau .\sigma \right) +\sigma .\bar{\partial}\partial _{H}\tau .
\end{equation*}

In view of the previous \emph{Lemma}, it remains to check that $\xi
_{H}\left( h,k\right) \wedge \omega ^{2}$ integrates to zero modulo terms of higher order:
\begin{equation*}
        \lim\limits_{S\rightarrow \infty }\int_{W_{S}}\xi _{H}\left( h,k\right)
        \wedge \omega ^{2}=0.
\end{equation*}

Taking account of bi-degree and de Rham's theorem, modulo terms with decay  $O( \left\vert\sigma\right\vert.\left\vert\tau\right\vert ^{2})
        +O( \left\vert\tau\right\vert.\left\vert\sigma\right\vert ^{2})$, one has 
\begin{eqnarray*}
        \int_{W_{S}}\xi _{H}\left( h,k\right) \wedge \omega ^{2} &=&\tfrac{1}{2}
        \int_{\partial W_{S}}\func{tr}\left[ \left( \tau .\bar{\partial}\sigma
        -\sigma .\bar{\partial}\tau \right) +\left( \partial _{H}\tau .\sigma
        -\partial _{H}\sigma .\tau \right)\right] \wedge \omega ^{2}\\ 
        &=&\tfrac{1}{2}\int_{\partial W_{S}}\func{tr}\left[ 2\tau .\bar{\partial}
        \sigma +2\partial _{H}\tau .\sigma -\nabla _{H}\left( \sigma .\tau\right)\right]
        \wedge \omega ^{2}\\
        &=&\int_{\partial W_{S}}\func{tr}\left( \tau .\bar{\partial}\sigma
        +\partial _{H}\tau .\sigma \right) \wedge \omega ^{2}
        \underset{S\rightarrow\infty}{\longrightarrow}0. 
\end{eqnarray*}

On the other hand, from (the Calabi-Yau-Tian-Kovalev) \emph{Theorem \ref{Thm SU(3) mfds}} [cf. $\left( \ref{asymptotic forms}
\right) $],
\begin{equation*}
        \left. \omega ^{2}\right\vert _{\partial W_{S}}
        =\kappa _{I}^{2}+O\left(\e{-S}\right).
\end{equation*}

Consequently, as $S\rightarrow\infty$, the operation `$.\,\wedge\, \omega ^{2}$' annihilates all components of the $
1-$form $\func{tr}\left( \tau .\bar{\partial}\sigma +\partial _{H}\tau
.\sigma \right)$ except those transversal to $D_{z}$ ($\left\vert
z\right\vert =\e{-S}$) in $\partial W_{S}\simeq D_{z}\times S^{1}$:
\begin{eqnarray*}
\int_{\partial W_{S}}\func{tr}\left( \tau .\bar{\partial}\sigma +\partial
_{H}\tau .\sigma \right) \wedge \omega ^{2} &=&\int_{\partial W_{S}}\func{
tr}\left( \tau .\frac{\partial \sigma }{\partial \bar{z}}d\bar{z}+\left( \left(\partial_{H}\tau \right)_{z} .\sigma dz\right)\wedge \left( \kappa _{I}^{2}+O\left( \e{-S}\right) \right) \right) \\
&= &\int_{\left\vert z\right\vert =e^{-S}}O\left( \left\vert
z\right\vert \right) \wedge \left( \kappa _{I}^{2}+O\left( \left\vert
z\right\vert \right) \right) \underset{\left\vert z\right\vert \rightarrow 0}
{\longrightarrow }0.
\end{eqnarray*}

Since $\mathcal{H}_{0}$ is simply connected, we conclude that
\index{norm!functional!$\mathcal{N}_{W}$} 
\begin{equation} \boxed{\; \mathcal{N}_{W}
        =\int_{\gamma }\rho _{W} \;}  
\end{equation}
doesn't depend on the choice of path $\gamma $.

Still following \cite[pp.8-11]{ASDYM}, by analogy with (\ref{eq def theta_H}) and (\ref{eq def rhoW}), define $\theta_{z} \in \Omega ^{1}\left( \mathcal{H}_{0},\Omega ^{1,1}\left( D_{z}\right) \right) $  by 
\begin{equation}
\begin{array}{c} \left(\theta_{z}\right) _{H}:T_{H}\mathcal{H}_{0}\rightarrow \Omega ^{1,1}\left( D_{z}\right) \\ 
\left(\theta_{z}\right) _{H}\left( k\right) =2\mathbf{i}\func{tr}
\left(\left.H\right\vert _{D_{z}}^{-1}.k.
\left.F_{H}\right\vert _{D_{z}}\right)
\end{array}.  
\end{equation}
and accordingly 
\begin{equation} \left( \rho _{D_z}\right) _{H}\left( k\right) 
        =\int_{D_{z}}\theta _{H}\left(k\right) \wedge \omega,
\end{equation}

Setting each $\mathcal{N}_{D_{z}}\left( H_{0}\right) =0$, and choosing, at first, a curve   $\gamma
\left( \ell \right) =\left. H_{\ell }\right\vert _{D_{z}}$ of
Hermitian metrics on $\left. \mathcal{E}\right\vert _{D_{z}}$, we write [cf. $
\left( \ref{eq def rhoW}\right)$]
\index{norm!functional!$\mathcal{N}_{D_z}$} 
\begin{equation}
\mathcal{N}_{D_{z}}:= \int_{\gamma }\rho _{D_{z}}=\int_{\gamma
}\int_{D_{z}}\theta \wedge \omega. \end{equation}

Each $D_{z}$
being a compact complex surface, it is known  [ibid.] that this definition of $\mathcal{N}
_{D_{z}}$ is in fact path-independent.

In view of \emph{Proposition \ref{Prop Uniform upper bound}} below, which underlies this article's main result [\emph{Theorem \ref{Thm MAIN THEOREM}}], one would like to
derive, for  small enough $\left\vert z\right\vert $, a time-uniform \emph{lower} bound on the `energy density' given by the $\omega-$trace of the restriction of curvature  $\left.F_{H_t}\right\vert _{D_{z}}$:
\begin{displaymath}
\widehat{F_{t\vert z}} := \widehat{\left.F_{H_t}\right\vert_{D_z}} = \left( \left.F_{H_t}\right\vert_{D_z} , \left.\omega \right\vert_{D_z}\right).
\end{displaymath}

Recalling that $\xi _{t}\in \Gamma \left( 
\func{End} \mathcal{E} \right) $ is defined by $H_{t}=H_{0}e^{\xi _{t}}$ (hence is self-adjoint with respect to both metrics), write $\bar{\lambda}_{t}$ for its highest eigenvalue as in $\left( \ref{eq def lambda bar}\right)$ and set 
\begin{displaymath}
        L_{t}:=\sup_{W}\bar{\lambda}_{t}.
\end{displaymath}

Fixing $t>0$ and $\left\vert z\right\vert $ $<\delta $, let us simplify notation by $\xi =\xi _{t}$ and $\left\Vert .\right\Vert =\left\Vert
.\right\Vert _{L^{2}\left( D_{z}\right) }$, and consider the curve
\begin{equation*}
\begin{array}{c}
\gamma :\left[ 0,1\right] \rightarrow \left. \mathcal{H}_{0}\right\vert
_{D_{z}} \\ 
\gamma \left( \ell \right) =H_{0}\e{\ell \xi }
\end{array}
\end{equation*}
with $\gamma \left( 1\right) =H_{t}$ and $\gamma _{\ell }^{-1}.\dot{\gamma}
_{\ell }=\xi $.

Form [cf. (\ref{eq def Phizao of l})]
\begin{equation*}
m\left( \ell \right) := \int_{0}^{\ell }\int_{D_{z}}\Phi ^{\gamma
}\left( \ell \right) \wedge \omega =2\mathbf{i}\int_{0}^{\ell }\left(
\int_{D_{z}}\xi .F_{\ell}\wedge \omega \right) d\ell
\end{equation*}
so that $m\left( 1\right) =\mathcal{N}_{D_{z}}\left( H_{t}\right)$ and $
m\left( 0\right) =0$; differentiating along $\gamma $ we have
\begin{equation*}
m^{\prime }\left( \ell \right) =2\mathbf{i}\int_{D_{z}}\xi .F_{\ell}\wedge \omega .
\end{equation*}

The function $m\left( \ell \right) $ is in fact convex:
\begin{displaymath}
        m^{\prime \prime }\left( \ell \right) 
        =2\mathbf{i}\int_{D_{z}}\func{tr}\xi .\left( \bar{\partial}_{\ell}
        \partial _{\ell }\xi \right) \wedge \omega 
        = 2\left\Vert \partial _{\ell }\xi \right\Vert ^{2}
        =\left\Vert \nabla_{\ell }\xi \right\Vert ^{2} \geq 0
\end{displaymath}
since $\xi $ is real, and so $\left\vert \partial _{\ell }\xi
\right\vert ^{2}=\left\vert \bar{\partial}_{\ell }\xi \right\vert ^{2}=\frac{
1}{2}\left\vert \nabla _{\ell }\xi \right\vert ^{2}$.

Finally, it can be shown that $\Delta\bar{\lambda}$ is (weakly) uniformly bounded \cite[p.246]{inf dets stab bdls...}, hence the maximum principle suggests that $\left\vert\xi_t\right\vert$ cannot `decrease faster' than a certain concave parabola along the cylindrical end. With that in mind, let us assume, for the sake of argument, that the following can be made rigorous:
\begin{quote}
In the terms of \emph{Claim \ref{claim (F hat)_L^2(Dz) > c  over large set}}, there exists a set $A_t$, `proportional' to $c'\sqrt{L_t}$, such that
\begin{equation*}
        \left\Vert \xi_{t}\right\Vert _{L^{\frac{4}{3}}\left( D_{z}\right)}
        \geq c_{2} \; L_{t} \qquad \forall t\in\left]0,\infty\right[,
\end{equation*}
where $c_2$ is independent of $t$ and $z$.
\end{quote}
Then, together with \emph{Lemma \ref{Lemma NDz > xi_L^4/3}} and \emph{Lemma \ref{Lemma Xsi bounds NDz}}, this would prove \emph{Claim \ref{claim (F hat)_L^2(Dz) > c  over large set}}, with
\begin{equation*}
c=\frac{2c_2}{c_1}\left(\inf_{\left\vert z \right\vert<\delta}{c_{z}}\right).
\end{equation*}
This is the heuristics underlying the proof, in the next \emph{Section}.

Recall that one would like to
establish, for  small enough $\left\vert z\right\vert $, a time-uniform \emph{lower} bound on the `energy density' given by the $\omega-$trace of the restriction  $\left.F_{H_t}\right\vert _{D_{z}}$:
\begin{displaymath}
\widehat{F_{t\vert z}} := \widehat{\left.F_{H_t}\right\vert_{D_z}} = \left( \left.F_{H_t}\right\vert_{D_z} , \left.\omega \right\vert_{D_z}\right),
\end{displaymath}
 in the \emph{weak} sense that its $L^2-$norm over a cylindrical segment $\Sigma$ far enough down the tubular end is bounded below by a scalar multiple of $\func{Vol} \Sigma$. Moreover, the length of such a cylinder $\Sigma$ can be assumed roughly proportional to $L_{t}:=\sup_{W}\bar\lambda_{t}$, so that $L_t\gg0$ implies a large `energy' contribution. This  will yield the $C^0-$bound in \emph{Proposition \ref{Prop Uniform upper bound}}.

The strategy here consists, on one hand, of using the weak control over the Laplacian from \emph{Lemma \ref{Lemma Delta Lambda weakly bounded}} below to show that, around the furthest point down the tube where $L_{t}=\max\limits_W \bar\lambda_t$ is attained, the slicewise supremum of $\bar\lambda_{t}$ is always on top of a certain concave parabola $P_t$. 
On the other hand, the integral along the tube of the slicewise norms $\Vert \bar\lambda\Vert_{L^\frac{4}{3}(D_z)}$, which bounds below $\mathcal{N}_{D_z}(H_t)$ [\emph{Lemma \ref{Lemma NDz > xi_L^4/3}}], can be shown to be itself bounded below by those slicewise suprema, using again the weak bound on the Laplacian to apply a Harnack estimate on `balls' of a standard shape, which fill essentially `half' of the corresponding tubular volume. 

Since $\mathcal{N}_{D_z}(H_t)$ is controlled above by $\hat F_{H_t}$, in the sense of \emph{Lemma \ref{Lemma Xsi bounds NDz}}, this leads to the desired minimal `energy' contribution, `proportional' to the length (roughly $\sqrt{L_t}$) of the tubular segment underneath the parabola $P_t$.

\subsubsection{Preliminary analysis} Here I establish some basic wording and technical facts underlying the proof.

\begin{definition} Given functions $f,g:W\rightarrow \mathbb{R}$, we denote
\begin{eqnarray*}
        \Delta f \overset{w}{\leq} g 
        &\dot\Leftrightarrow&
        \int_W f\Delta\varphi \leq \int_W g\varphi ,
        \quad \forall \varphi\in C_c^\infty (W,\mathbb{R}^+).
\end{eqnarray*} 
In particular, a constant $\beta\in\mathbb{R}$ is called a \emph{weak bound on the Laplacian of $f$} if $\Delta f \overset{w}{\leq}\beta$
\end{definition}
The following \emph{Lemma} is intuitively assumed in  \cite[p.246]{inf dets stab bdls...}, so the proof may also interest careful readers of that reference.
\begin{lemma}[weak maximum principle] Let $f:W\to\mathbb{R}$ be a (nonconstant) nonnegative Lipschitz function, smooth away from a singular set $N_0$ with $\func{codim} N_0\geq3$; if $\Delta f\overset{w}{\leq} 0$ [cf. \emph{Definition \ref{def weak bound on Laplacian}}] over a (bounded open) domain $U\subset W$, then $$\left. f \right\vert_{U}\leq \max\limits_{\partial U} f.$$

\begin{proof}
Outside of an  $\varepsilon-$neighbourhood $N_\varepsilon$ of the singular set $N_0$, the function $f$ is smooth, so the strong maximum principle on $U\smallsetminus N_\varepsilon$ implies, at the limit $\varepsilon\to0$, that any interior maximum point $q\in U$ must be in $N_0$.
Take then a (small) coordinate neighbourhood $q\in V\Subset U$ such that the gradient field $\nabla f$ `points inwards' to $q$ almost everywhere (a.e.) along $\partial V$. 

I claim one can choose  test functions  $\varphi\in C^\infty_c(W,\mathbb{R}^+)$,  with $\func{supp}(\varphi)\subset V$, such that  $\left(\nabla f,\nabla\varphi\right)$ is  practically nonnegative, in a suitable sense. Since $f$ is Lipschitz and a.e. differentiable, $f\in L^2_{1,loc}(W)\hookrightarrow L^2_1(V)$; by density, for every $\delta>0$ there exists $\varphi_\delta\in C^\infty_c(V)\hookrightarrow C^\infty_c(W)$ such that 
$$
\left\Vert f-\varphi_\delta\right\Vert^2_{L^2_1(V)}<\delta.
$$
Moreover, since $f$ is (nonconstant and) nonnegative and $q$ is a maximum, we may assume without loss that $\varphi_\delta\geq0$, so $\varphi_\delta$ is indeed a test function on $V$. Then 
\begin{eqnarray*}
        0\geq \int_W f\Delta\varphi_\delta
        =\int_V f\Delta\varphi_\delta
        =\lim_{\varepsilon\to0}\int_{V\smallsetminus N_\varepsilon}f\Delta\varphi_\delta
        \overset{(*)}{=} \int_V \left( \nabla f,\nabla\varphi_\delta \right)
        >-\delta
        \underset{\delta\to0}{\longrightarrow}0
\end{eqnarray*}
which either iterates all over $U$ to imply $f\equiv \max\limits_{\partial U} f$ or contradicts the assumption that $q$ is an interior point. Step $(*)$ is rigorous because $N_0$ has large enough codimension so that $\left.\:d\func{Vol}_\omega\right\vert_{\partial N_\varepsilon}=O(\varepsilon^2)$. Thus boundary terms in the integration by parts over $V\smallsetminus N_\varepsilon$ vanish when $\varepsilon\rightarrow 0$, again since $f$ is Lipschitz \cite[p.244]{inf dets stab bdls...}.
\end{proof}
\end{lemma}



Recalling that $\xi _{t}\in \Gamma \left( 
\func{End} \mathcal{E} \right) $ is defined by $H_{t}=H_{0}e^{\xi _{t}}$ (hence is self-adjoint with respect to both metrics), write $\bar{\lambda}_{t}$ for its highest eigenvalue; then:

\begin{lemma} The Laplacian of $\bar\lambda$ admits a weak bound $\beta>0$:
\begin{displaymath}
        \Delta\bar\lambda_t \overset{w}{\leq} \beta, \qquad\forall t>0. 
\end{displaymath}
\begin{proof}
We know from \cite[Lemma 25]{inf dets stab bdls...} that\begin{displaymath}
        \Delta\bar\lambda \overset{w}{\leq} 
        2 \left( \left\Vert \hat{F}_{H_t} \right\Vert_{H_t} 
        + \left\Vert \hat{F}_{H_0} \right\Vert_{H_0}\right),
\end{displaymath}
and the right-hand side is controlled by the time-uniform bound on $\hat{F}_{H_t}$ [\emph{Corollary \ref{Cor Bounded F hat}}].
\end{proof}
\end{lemma}


\begin{lemma} Let $\left(D,g\right)$ be a compact Riemannian manifold, $f\in L^\infty\left(D,\mathbb{R}^+\right)$,  $p>1$ and $x>0$; then there exists a constant $k_p=k_p\left(D,g\right)>0$ such that
\begin{displaymath}
        \left\Vert f\right\Vert_p \geq \frac{k_p}{F^x}\left\Vert f^{1+x}         \right\Vert_1
\end{displaymath}
with $\left\Vert.\right\Vert_q:=\left\Vert . \right\Vert_{L^q\left(D,g\right)},1<q\leq\infty,$ and $F:= \left\Vert f \right\Vert_\infty$.
\begin{proof}
It suffices to write
\begin{displaymath}
        \left\Vert f \right\Vert_p := \left(\int_D f^p \; d\func{Vol}_g\right)^{\frac{1}{p}}
        \geq \left(\int_D f^p\left( \frac{f}{F} \right)^{xp}
        d\func{Vol}_g\right)^{\frac{1}{p}} \\
        = F^{-x} \left\Vert f^{1+x} \right\Vert_p
\end{displaymath}
then apply H\"older's inequality, finding $k_p=\func{Vol}_g(D)^{\frac{1}{p}-1}$.
\end{proof}
\end{lemma}

\subsubsection{A concave parabola as lower bound}
In tubular coordinates $\left\vert z\right\vert=\e{-s}$, the supremum of $\bar\lambda_t$ on a transversal slice along $W_\infty$ defines a smooth function
\begin{displaymath}
\begin{array}{rcrcl}
        \ell_t&:&\mathbb{R}^+&\rightarrow&\mathbb{R}^+\\
        &&\ell_t(s)&:=& \sup\limits_{\partial W_s} \bar\lambda_t.\\
\end{array}
\end{displaymath}
Moreover, for each $t>0$, denote $S_t$ the `furthest length' down the tube at which $L_t$ is attained, i.e., $S_t=\max \left\{s\geq0\left\vert L_t=\ell_t\left( s \right)\right.\right\}$, and set
\begin{displaymath}
        I_t := \left[ S_t,S_t + \delta^{+}_t\right]\subset \mathbb{R}^+
\end{displaymath}
with $\delta^{+}_t:= \frac{1}{2}\left(\sqrt{1+\frac{8}{\beta}L_t}-1\right)$ and $\beta$ as in \emph{Lemma \ref{Lemma Delta Lambda weakly bounded}}.
\begin{lemma} For each $t>0$, the transversal supremum $\ell_t$ is bounded below over $I_t$ by the concave parabola $P_t(s-S_t):= L_t -\frac{\beta}{2}(s-S_t)(s-S_t+1)$, i.e.,
\begin{displaymath}
        \ell_t(s)\geq P_t(s), \quad \forall s\in I_t.
\end{displaymath}
\begin{proof}
Fix $t>0$, $\delta^+_t\geq\delta>0$ and set $J_t\left( \delta \right):= \left]S_{t}-1,S_{t}+\delta\right[ $ (I suppress henceforth the $t$ subscript everywhere, for clarity). The parabola takes the value $P(-1)=P(0)=L$ at the points $S-1$ and $S$, and its concavity $-P''_t=\beta$ is precisely the weak bound on $\Delta\bar\lambda$ [\emph{Lemma \ref{Lemma Delta Lambda weakly bounded}}], so we have $\Delta\left( \bar\lambda - P\right)\overset{w}{\leq}0$ on $\overline{J(\delta)}$ and  \emph{Lemma \ref{lemma weak max principle}} gives
\begin{eqnarray*}
         \left.\left( \bar\lambda - P \right)\right\vert_{J(\delta)}
        &<& \max \left\{ 
        \sup\limits_{s=S-1} \left( \bar\lambda - P \right),  
        \sup\limits_{s=S+\delta}\left( \bar\lambda - P \right)\right\}\\
        \Rightarrow \quad0=\ell(S)-P(S) &<& \ell(S+\delta)-P(S+\delta),
        \quad \forall 0<\delta<\delta^+ 
\end{eqnarray*}
since by assumption $\ell(S-1)\leq L=P(-1)$. Hence $\ell\geq P,\quad \forall s\in I$.
\end{proof}
\end{lemma}

\begin{remark} Fixing $0<\epsilon<1$ and setting $\delta^+_{\epsilon,t}:=\frac{1}{2}\left(\sqrt{1+\frac{8}{\beta}(1-\epsilon)L_t}-1\right)$, one has\begin{equation} \ell_t(s) \geq \epsilon L_t, \quad \forall s\in I_{\epsilon,t}
        :=\left[ S_t,S_t+\delta^+_{\epsilon,t} \right].
\end{equation}
Clearly, if $L_t\to\infty$, the interval length grows quadratically as fast:
$$\frac{\delta^+_{\epsilon,t}}{\sqrt{L_t}}\to c_\epsilon':=\sqrt{\frac{2(1-\epsilon)}{\beta}}.
$$
\end{remark}



Moreover, we can use a Harnack-type estimate over transversal slices to establish the following inequality for the finite cylinder under the parabola:
\begin{lemma} Given $t>0$ and $0<\epsilon<1$, let $\Sigma_{t}(\epsilon):= I_{\epsilon,t}\times D \simeq \overline{W_{S_t+\delta^+_{\epsilon,t}}\setminus W_{S_t}}$ be the finite cylinder along $W$, under the parabola $P_t$ of \emph{Lemma \ref{lemma parabola}}, determined by the interval of length $\delta^+_{\epsilon,t}$ on which $(\ref{eq ell bounded below})$ holds, and suppose ${2\mathbf{\pi}}\delta^+_{\epsilon,t}\in\mathbb{N}$; then, for each $x>0$, there exist time-uniform constants $ a_{x,\epsilon},b_{x,\epsilon}>0$ such that, if $L_t>b_{x,\epsilon}$, the following estimate holds:
\begin{equation} \int_{\Sigma_{t}(\epsilon)}\bar\lambda_t^{1+x} \; 
        d\func{Vol}_{\omega_\infty} 
        \geq a_{x,\epsilon} 
        \cdot \delta^+_{\epsilon,t}
        \cdot \left(L_t-b_{x, \epsilon} \right)^{1+x}. 
\end{equation}
\begin{proof}  
Again let me suppress the $t$ subscript, for tidiness, and work all along in the cylindrical metric $\omega_\infty$. For each $s\in I_\epsilon$, let $p_s\in \partial W_s \simeq D_s\times S^1$ be a point on the corresponding transversal slice such that the maximum $\ell(s)=\bar\lambda(p_s)$ is attained, and form the `unit' open cylinder $B_s\subset \Sigma_\epsilon$ of length $\frac{1}{2\mathbf{\pi}}$ (so that the volume integral over $B_s$ along the $S^1\times I_\epsilon$ directions is 1), centered on $p_s$, such that 
\begin{displaymath}
        \func{Vol} B_s = \func{Vol} \left( B_s\cap D_s \right) = \frac{1}{2} \func{Vol} D,
\end{displaymath}
where $\func{Vol} D\equiv \func{Vol} D_s$ denotes the (same) four-dimensional volume of (every) $D_s$.

By \emph{Lemma \ref{Lemma Delta Lambda weakly bounded}}, $\bar\lambda$ is a weak subsolution of the elliptic problem $\Delta u=\beta$, so we may apply Moser's iteration method   \cite[Theorem 8.25]{Gilb-Trud}\cite[Theorem 2]{Moser} over an open set $V$ such that $\partial W_s\subset V\subset B_s$ to obtain local boundedness of $\bar\lambda$ in terms of its $L^{1+x}(B_s,\omega_\infty)-$norm. Indeed we can choose $V$ such that:   
$$
\ell(s)
\leq 
C_x\left[
        \left( 
        \frac{1}{\func{Vol} B_s}
        \right)^{\frac{1}{1+x}}
        \left\Vert\bar\lambda\right\Vert_{1+x} +1
\right]
$$
for some constant $C_x=C_x(B_s,\beta,x)>0$ which in fact is uniform in $s$, as all $B_s$ are congruent by translation. Setting $\displaystyle b_{x,\epsilon}:=\frac{C_x}{\epsilon}$ and using (\ref{eq ell bounded below}) we have
\begin{equation} \left[
        \epsilon \left(L-b_{x,\epsilon}\right)
        \right]^{1+x}
\leq
\frac{1}{\func{Vol} B_s}\int_{B_s}\bar\lambda^{1+x}.
\end{equation}
In particular, one can choose at most $2\mathbf{\pi}\delta^+_\epsilon\in \mathbb{N}$ values $s_j\in I_\epsilon$ such that the corresponding $B_{s_j}$ are necessarily disjoint, and form their union 
\begin{displaymath}
        B\left( \epsilon \right):=\coprod\limits_{j=1}^{2\mathbf{\pi}\delta^+_\epsilon}
        B_{s_j}.
\end{displaymath}
Clearly $\func{Vol} B(\epsilon)\geq \frac{1}{2}\left(2\mathbf{\pi}\delta^+_\epsilon\right)\func{Vol} D$. Now, the statement about averages $(\ref{eq Moser})$ goes over to the disjoint union, hence
\begin{displaymath}
        \int_{\Sigma(\epsilon)}\bar\lambda^{1+x} 
        \geq \int_{B(\epsilon)}\bar\lambda^{1+x}
        \geq \func{Vol} B(\epsilon) 
        \cdot 
        \left[
        \epsilon \left(L-b_{x,\epsilon}\right)
        \right]^{1+x}
\end{displaymath}
 which proves the \emph{Lemma}, with 
 $a_{x, \epsilon} := \left(\mathbf{\pi} \func{Vol} D\right)\epsilon^{1+x}$.
\end{proof}
\end{lemma}


\subsubsection{End of proof}

It is now just a matter of putting together the previous results. Recalling the final remarks of \emph{Subsection \ref{Subsec conjectured uniform Lp-bound}}, we know from  \emph{Lemma \ref{Lemma NDz > xi_L^4/3}} and \emph{Lemma \ref{Lemma Xsi bounds NDz}} that
\begin{displaymath}
