\end{eqnarray*}
which yields the \emph{Claim}, choosing e.g. $\epsilon=\frac{1}{2}$, $x=1$ and [cf. \emph{Remark \ref{rem delta+,epsilon,t}}]
\begin{displaymath}
        c=
        \left( 
        \frac{k'' \cdot a_{1,\frac{1}{2}}}{\sqrt{2}\mathbf{\pi}}
        \right)^2 
        =
        \frac{\left(k'\right)^2\left(\func{Vol} D\right)^{\frac{3}{2}}}{32}
        \quad \text{and} \quad   
