\end{displaymath}
where $\func{Vol} D\equiv \func{Vol} D_s$ denotes the (same) four-dimensional volume of (every) $D_s$.

By \emph{Lemma \ref{Lemma Delta Lambda weakly bounded}}, $\bar\lambda$ is a weak subsolution of the elliptic problem $\Delta u=\beta$, so we may apply Moser's iteration method   \cite[Theorem 8.25]{Gilb-Trud}\cite[Theorem 2]{Moser} over an open set $V$ such that $\partial W_s\subset V\subset B_s$ to obtain local boundedness of $\bar\lambda$ in terms of its $L^{1+x}(B_s,\omega_\infty)-$norm. Indeed we can choose $V$ such that:   
$$
\ell(s)
\leq 
C_x\left[
        \left( 
        \frac{1}{\func{Vol} B_s}
        \right)^{\frac{1}{1+x}}
        \left\Vert\bar\lambda\right\Vert_{1+x} +1
\right]
$$
for some constant $C_x=C_x(B_s,\beta,x)>0$ which in fact is uniform in $s$, as all $B_s$ are congruent by translation. Setting $\displaystyle b_{x,\epsilon}:=\frac{C_x}{\epsilon}$ and using (\ref{eq ell bounded below}) we have
\begin{equation} \left[
        \epsilon \left(L-b_{x,\epsilon}\right)
        \right]^{1+x}
\leq
\frac{1}{\func{Vol} B_s}\int_{B_s}\bar\lambda^{1+x}.
\end{equation}
In particular, one can choose at most $2\mathbf{\pi}\delta^+_\epsilon\in \mathbb{N}$ values $s_j\in I_\epsilon$ such that the corresponding $B_{s_j}$ are necessarily disjoint, and form their union 
\begin{displaymath}
        B\left( \epsilon \right):=\coprod\limits_{j=1}^{2\mathbf{\pi}\delta^+_\epsilon}
        B_{s_j}.
\end{displaymath}
Clearly $\func{Vol} B(\epsilon)\geq \frac{1}{2}\left(2\mathbf{\pi}\delta^+_\epsilon\right)\func{Vol} D$. Now, the statement about averages $(\ref{eq Moser})$ goes over to the disjoint union, hence
\begin{displaymath}
        \int_{\Sigma(\epsilon)}\bar\lambda^{1+x} 
        \geq \int_{B(\epsilon)}\bar\lambda^{1+x}
        \geq \func{Vol} B(\epsilon) 
        \cdot 
        \left[
        \epsilon \left(L-b_{x,\epsilon}\right)
        \right]^{1+x}
\end{displaymath}
 which proves the \emph{Lemma}, with 
 $a_{x, \epsilon} := \left(\mathbf{\pi} \func{Vol} D\right)\epsilon^{1+x}$.
\end{proof}
\end{lemma}

It is now just a matter of putting together the previous results. Recalling the final remarks of \emph{Subsection \ref{Subsec conjectured uniform Lp-bound}}, we know from  \emph{Lemma \ref{Lemma NDz > xi_L^4/3}} and \emph{Lemma \ref{Lemma Xsi bounds NDz}} that
\begin{displaymath}
        L\Vert \hat F \Vert_2 \geq k'
        \left( \left\Vert \bar\lambda\right\Vert_{\frac{4}{3}} -1\right)
\end{displaymath}  
over each $D_z$ sufficiently far down the tube, for a uniform constant $k'>0$. Choosing $0<\epsilon<1$ and $x>0$, integrating over $A_\epsilon:= I_\epsilon\times S^1$ and applying \emph{Lemma \ref{lemma p-norm and 1-norm}} we have
\begin{displaymath}
        \int_{A_\epsilon} \Vert \hat F \Vert_2  \;ds\wedge d\alpha
        \geq  \frac{k''}{L^{1+x}}
        \left(\int_{A_\epsilon}\left\Vert \bar\lambda^{1+x} \right\Vert_1 
        ds\wedge d\alpha \right)
        -k'\frac{\delta_\epsilon^+}{L}
\end{displaymath}
where $k'':= k' \cdot k_\frac{4}{3}$ is still a uniform constant. Moreover, by \emph{Lemma \ref{lemma Moser}}, the integral term is bounded below by 
$k'' \cdot a_{x,\epsilon} \cdot\delta^+_{\epsilon } \cdot
        \left(1-\frac{b_{x, \epsilon}}{L} \right)^{1+x}$, so H\"older's inequality gives
\begin{eqnarray*}
        \left(\func{Vol} A_\epsilon \right)^{\frac{1}{2}}
        \left(\int_{A_\epsilon}\Vert \hat F \Vert_2^2 \; ds\wedge d\alpha\right)^\frac{1}{2}
        &\geq& \delta^+_{\epsilon}
        \left(
                k'' \cdot a_{x,\epsilon}  \cdot 
                \left(1-\frac{b_{x, \epsilon}}{L} \right)^{1+x} 
                -\frac{k'}{L}
        \right).
\end{eqnarray*}
Since the interval $I_\epsilon$ has length precisely $\delta^+_\epsilon$, we have
$\mu_{\infty}\left( A_\epsilon \right)=\func{Vol} A_\epsilon =2\mathbb{\pi}\delta^+_\epsilon$ and so
\begin{eqnarray*}
         \int_{A_\epsilon}\Vert \hat F \Vert_2^2 \; ds\wedge d\alpha         &\geq& \frac{\mu_{\infty}\left( A_\epsilon \right)}{4\mathbb{\pi}^2}
    \left(
                k'' \cdot a_{x,\epsilon}  \cdot 
                \left(1-\frac{b_{x, \epsilon}}{L} \right)^{1+x} 
                -\frac{k'}{L}
        \right)^2
\end{eqnarray*}
which yields the \emph{Claim}, choosing e.g. $\epsilon=\frac{1}{2}$, $x=1$ and [cf. \emph{Remark \ref{rem delta+,epsilon,t}}]
\begin{displaymath}
        c=
        \left( 
        \frac{k'' \cdot a_{1,\frac{1}{2}}}{\sqrt{2}\mathbf{\pi}}
        \right)^2 
        =
        \frac{\left(k'\right)^2\left(\func{Vol} D\right)^{\frac{3}{2}}}{32}
        \quad \text{and} \quad   
        c'=2\mathbb{\pi}\sqrt{\frac{1}{\beta}}.\\
\end{displaymath}

Recalling the final remarks of \emph{Subsection \ref{Subsec conjectured uniform Lp-bound}}, we know from  \emph{Lemma \ref{Lemma NDz > xi_L^4/3}} and \emph{Lemma \ref{Lemma Xsi bounds NDz}} that
\begin{displaymath}
        L\Vert \hat F \Vert_2 \geq k'
        \left( \left\Vert \bar\lambda\right\Vert_{\frac{4}{3}} -1\right)
\end{displaymath}  
over each $D_z$ sufficiently far down the tube, for a uniform constant $k'>0$.

Choosing $0<\epsilon<1$ and $x>0$, integrating over $A_\epsilon:= I_\epsilon\times S^1$ and applying \emph{Lemma \ref{lemma p-norm and 1-norm}} we have
\begin{displaymath}
        \int_{A_\epsilon} \Vert \hat F \Vert_2  \;ds\wedge d\alpha
        \geq  \frac{k''}{L^{1+x}}
        \left(\int_{A_\epsilon}\left\Vert \bar\lambda^{1+x} \right\Vert_1 
        ds\wedge d\alpha \right)
        -k'\frac{\delta_\epsilon^+}{L}
\end{displaymath}
where $k'':= k' \cdot k_\frac{4}{3}$ is still a uniform constant.

Moreover, by \emph{Lemma \ref{lemma Moser}}, the integral term is bounded below by 
$k'' \cdot a_{x,\epsilon} \cdot\delta^+_{\epsilon } \cdot
        \left(1-\frac{b_{x, \epsilon}}{L} \right)^{1+x}$, so H\"older's inequality gives
\begin{eqnarray*}
        \left(\func{Vol} A_\epsilon \right)^{\frac{1}{2}}
        \left(\int_{A_\epsilon}\Vert \hat F \Vert_2^2 \; ds\wedge d\alpha\right)^\frac{1}{2}
        &\geq& \delta^+_{\epsilon}
        \left(
                k'' \cdot a_{x,\epsilon}  \cdot 
                \left(1-\frac{b_{x, \epsilon}}{L} \right)^{1+x} 
                -\frac{k'}{L}
        \right).
\end{eqnarray*}

Since the interval $I_\epsilon$ has length precisely $\delta^+_\epsilon$, we have
$\mu_{\infty}\left( A_\epsilon \right)=\func{Vol} A_\epsilon =2\mathbb{\pi}\delta^+_\epsilon$ and so
\begin{eqnarray*}
         \int_{A_\epsilon}\Vert \hat F \Vert_2^2 \; ds\wedge d\alpha         &\geq& \frac{\mu_{\infty}\left( A_\epsilon \right)}{4\mathbb{\pi}^2}
    \left(
                k'' \cdot a_{x,\epsilon}  \cdot 
                \left(1-\frac{b_{x, \epsilon}}{L} \right)^{1+x} 
                -\frac{k'}{L}
        \right)^2
\end{eqnarray*}
which yields the \emph{Claim}, choosing e.g. $\epsilon=\frac{1}{2}$, $x=1$ and [cf. \emph{Remark \ref{rem delta+,epsilon,t}}]
\begin{displaymath}
        c=
        \left( 
        \frac{k'' \cdot a_{1,\frac{1}{2}}}{\sqrt{2}\mathbf{\pi}}
        \right)^2 
        =
        \frac{\left(k'\right)^2\left(\func{Vol} D\right)^{\frac{3}{2}}}{32}
        \quad \text{and} \quad   
        c'=2\mathbb{\pi}\sqrt{\frac{1}{\beta}}.\\
\end{displaymath}

In tubular coordinates $\left\vert z\right\vert=\e{-s}$, the supremum of $\bar\lambda_t$ on a transversal slice along $W_\infty$ defines a smooth function
\begin{displaymath}
\begin{array}{rcrcl}
        \ell_t&:&\mathbb{R}^+&\rightarrow&\mathbb{R}^+\\
        &&\ell_t(s)&:=& \sup\limits_{\partial W_s} \bar\lambda_t.\\
\end{array}
\end{displaymath}

Moreover, for each $t>0$, denote $S_t$ the `furthest length' down the tube at which $L_t$ is attained, i.e., $S_t=\max \left\{s\geq0\left\vert L_t=\ell_t\left( s \right)\right.\right\}$, and set
\begin{displaymath}
        I_t := \left[ S_t,S_t + \delta^{+}_t\right]\subset \mathbb{R}^+
\end{displaymath}
with $\delta^{+}_t:= \frac{1}{2}\left(\sqrt{1+\frac{8}{\beta}L_t}-1\right)$ and $\beta$ as in \emph{Lemma \ref{Lemma Delta Lambda weakly bounded}}.

Fix $t>0$, $\delta^+_t\geq\delta>0$ and set $J_t\left( \delta \right):= \left]S_{t}-1,S_{t}+\delta\right[ $ (I suppress henceforth the $t$ subscript everywhere, for clarity). The parabola takes the value $P(-1)=P(0)=L$ at the points $S-1$ and $S$, and its concavity $-P''_t=\beta$ is precisely the weak bound on $\Delta\bar\lambda$ [\emph{Lemma \ref{Lemma Delta Lambda weakly bounded}}], so we have $\Delta\left( \bar\lambda - P\right)\overset{w}{\leq}0$ on $\overline{J(\delta)}$ and  \emph{Lemma \ref{lemma weak max principle}} gives
\begin{eqnarray*}
         \left.\left( \bar\lambda - P \right)\right\vert_{J(\delta)}
        &<& \max \left\{ 
        \sup\limits_{s=S-1} \left( \bar\lambda - P \right),  
        \sup\limits_{s=S+\delta}\left( \bar\lambda - P \right)\right\}\\
        \Rightarrow \quad0=\ell(S)-P(S) &<& \ell(S+\delta)-P(S+\delta),
        \quad \forall 0<\delta<\delta^+ 
\end{eqnarray*}
since by assumption $\ell(S-1)\leq L=P(-1)$.

For each $s\in I_\epsilon$, let $p_s\in \partial W_s \simeq D_s\times S^1$ be a point on the corresponding transversal slice such that the maximum $\ell(s)=\bar\lambda(p_s)$ is attained, and form the `unit' open cylinder $B_s\subset \Sigma_\epsilon$ of length $\frac{1}{2\mathbf{\pi}}$ (so that the volume integral over $B_s$ along the $S^1\times I_\epsilon$ directions is 1), centered on $p_s$, such that 
\begin{displaymath}
        \func{Vol} B_s = \func{Vol} \left( B_s\cap D_s \right) = \frac{1}{2} \func{Vol} D,
\end{displaymath}
where $\func{Vol} D\equiv \func{Vol} D_s$ denotes the (same) four-dimensional volume of (every) $D_s$.

In particular, one can choose at most $2\mathbf{\pi}\delta^+_\epsilon\in \mathbb{N}$ values $s_j\in I_\epsilon$ such that the corresponding $B_{s_j}$ are necessarily disjoint, and form their union 
\begin{displaymath}
        B\left( \epsilon \right):=\coprod\limits_{j=1}^{2\mathbf{\pi}\delta^+_\epsilon}
        B_{s_j}.
\end{displaymath}
Clearly $\func{Vol} B(\epsilon)\geq \frac{1}{2}\left(2\mathbf{\pi}\delta^+_\epsilon\right)\func{Vol} D$.

Now, the statement about averages $(\ref{eq Moser})$ goes over to the disjoint union, hence
\begin{displaymath}
        \int_{\Sigma(\epsilon)}\bar\lambda^{1+x} 
        \geq \int_{B(\epsilon)}\bar\lambda^{1+x}
        \geq \func{Vol} B(\epsilon) 
        \cdot 
        \left[
        \epsilon \left(L-b_{x,\epsilon}\right)
        \right]^{1+x}
\end{displaymath}
 which proves the \emph{Lemma}, with 
 $a_{x, \epsilon} := \left(\mathbf{\pi} \func{Vol} D\right)\epsilon^{1+x}$.

Concretely, this would mean improving the constant $C_{T}$ in $\left( \ref
{eq bound on sigma}\right) $ to a time-uniform bound $C_{\infty }$ or, what is the same, controlling the sequence $\bar{\lambda}_{t}$ of highest
eigenvalues of $\xi _{t}=\log H_{0}^{-1}H_{t}$ [cf. $\left( \ref{eq def lambda bar}\right) $]:
\begin{equation}
\boxed{\begin{array}{cr}
\left\Vert \bar{\lambda}_{t}\right\Vert _{C^{0}\left( W\right) }\leq
C_{\infty },& \forall t>0. \\
\end{array}  } \end{equation}

On the other hand, the Hodge-Riemann  equation $\left( \ref{Eq Hodge-Riemann}\right) $ [see \emph{Appendix A}] reads
 \begin{equation*}
        \func{tr}F^{2}\wedge \omega 
        =\left( \vert F^{\perp }\vert^{2}
        -\vert \hat{F}\vert ^{2}\right) \omega ^{3}.
\end{equation*}

Comparing we find $\left\vert F\right\vert ^{2}\omega ^{3}=\func{tr}F^{2}\wedge \omega +2\vert \hat{F}\vert ^{2}\omega ^{3}$ [cf. \emph{Subsection \ref{Sub energy bounds}}], so
\begin{eqnarray*}
        E(t)&=&\int_{W}\left(\func{tr}F_{H_{t}}^{2}
        -\func{tr}F_{H_{0}}^{2}\right)\wedge \omega
        +2 \int_{W}\left(\hat{e}_t - \hat{e}_0\right)\omega ^{3}\\
        \overset{\frac{d}{dt}}{\Longrightarrow}\quad
        \dot{E}(t)&\leq&\int_W \left(-\mathbf{i}\bar{\partial}\partial           \Phi_t\right)\wedge\omega +2\int_W\left(-\Delta\hat{e}_t\right)\omega^{3}\\
        &\leq&\lim_{S\rightarrow\infty}\int_{\partial W_S}
        2\left[\partial \func{tr} \left(\hat{F}_{H_t}.F_{H_t}\right)\wedge\omega
        +\frac{\partial\hat{e}_t}{\partial\nu} \left.\:d\func{Vol}_\omega\right\vert_{\partial         W_S}\right]\\
        &=&0
\end{eqnarray*}
using \emph{Lemma \ref{lemma: trF^2 and Phizao}}
along with its \emph{Proof} and $\left(\frac{d}{dt}+\Delta\right)\hat{e}_t \leq 0$ as in $(\ref{eq (d/dt+D)e^ < 0})$, then complex integration by parts [\emph{Lemma \ref{Lemma integration by parts on W}} in \emph{Appendix \ref{App exterior algebra}}] and the Gauss-Ostrogradsky theorem, and finally the exponential decay $\hat{F}_{H_t} \overset{C^\infty}{\underset{S\rightarrow\infty}{\longrightarrow}} 0$, a direct consequence from \emph{Proposition \ref{Prop e hat decays exponentially along S}} and \emph{Corollary \ref{Cor H -> H0 exponentially in all derivatives}}. This shows that $E(t)$ is non-increasing, while obviously $E(0)=0$.

Reasoning as above we find, for a Chern connection on $\left.\mathcal{E}\right\vert_{D_s}$,
\begin{equation} \left\vert F\right\vert ^{2}\omega ^{2}=\func{tr}F^{2}
+2\vert \hat{F}\vert ^{2}\omega ^{2}.
\end{equation}

Moreover, around each $D_s$ we have
$\displaystyle
        {\left.\:d\func{Vol}_\omega\right\vert_{D_s}} 
        = \tfrac{1}{2}\left(\left.\omega\right\vert_{D_s}\right)^2 
        = \left.\tfrac{1}{2}\left(\kappa_I +d\psi \right)^2 \right\vert_{D_s}
$,
so that 
\begin{eqnarray} \:d\text{V}_{tub}&=&ds\wedge d\alpha\wedge{\left.\:d\func{Vol}_\omega\right\vert_{D_s}}.
\end{eqnarray}

The Hodge-Riemann property  (\ref{Eq energy bound on surface Ds}) and the decomposition (\ref{eq tubular decomp volume forms}) then give, by Fubini's theorem,
\begin{eqnarray*}
        \int_{\Sigma} \left(\left\vert F_0 \right\vert^2 -R_0 \right)
        \:d\text{V}_{tub}
        &=& \int_{A} \left\{\int_{D_{s}}\left\vert F_{0\vert s} \right\vert^2
        \left.\:d\func{Vol}_\omega\right\vert_{D_s}\right\} ds\wedge d\alpha \\
        &=& \int_{A} \left\langle c_2\left( \left.\mc{E}\right\vert_{D_s}\right),\left[ D_s \right]\right\rangle
        ds\wedge d\alpha.        
\end{eqnarray*}

Then the \emph{Lemma}  gives a lower  estimate on the curvature over $\Sigma_t$:
\begin{eqnarray} \quad\int_{\Sigma_t} \left(\left\vert F_t\right\vert^2
        - \left\vert F_0 \right\vert^2 +R_0\right) 
        \:d\text{V}_{tub}         &\geq&2 \int_{A_t} \Vert \widehat{F_{t \vert s}} \Vert^2_{L^2(D_s)}
        ds\wedge d\alpha.
\end{eqnarray}

On the other hand, in the actual metric $\:d\func{Vol}_\omega$ we have:
\begin{eqnarray*}
        E(t)&=&\left(\int_{W_0}+\int_{W_\infty} \right)
        \left(\left\vert F_t\right\vert^2
        - \left\vert F_0 \right\vert^2 \right) 
        \:d\func{Vol}_\omega\\
        &\geq&
       -\left\Vert F_0\right\Vert^2 _{L^2(W_0,\omega)} 
        + \int_{W_\infty}
        \left(\left\vert F_t\right\vert^2
        - \left\vert F_0 \right\vert^2\right) 
        \:d\func{Vol}_\omega.
\end{eqnarray*}

Then 
\begin{eqnarray*}
        c.\mu_{\infty}\left( A_t \right) 
        &\leq& \left(\sup_W f\right)\left(E(t)
        +\left\Vert F_0\right\Vert^2 _{L^2(W_0,\omega)} 
        +\left\Vert R_{0}\right\Vert_{L^1(W,\omega)}\right)
\end{eqnarray*}
 and we know from the negative energy condition (\ref{eq uniform energy bound}) that this is bounded above, uniformly in $t$.

Hence the cylinder $\Sigma_t$ cannot stretch indefinitely and, by contradiction, there must exist a uniform upper bound$$ 
C_\infty \simeq 
\left[
\frac
{\sup f} 
{c.c''}
\left(\left\Vert F_0\right\Vert^2 _{L^2(W_0)} 
+\left\Vert R_{0}\right\Vert_{L^1(W)}
\right)
\right]^2.\qedhere
$$

assumptions:
let $\left\{
H_{t}=H_{0}e^{\xi _{t}}\right\} $ be the $1-$parameter family of Hermitian
metrics on $\mathcal{E}$ given by \emph{Theorem \ref{thm sols for all time and exponentially decaying}}

nodes.statement:
Those are called \emph{instanton monads} and have the form
\begin{equation} \begin{array}{ccccccccc}
0 & \rightarrow & \mathcal{O}_X\left(-1\right)^{\oplus c} & \overset{\alpha}{\longrightarrow} & \mathcal{O}_X^{\oplus2+2c} & \overset{\beta}{\longrightarrow} & \mathcal{O}_X\left(1\right)^{\oplus c} & \rightarrow & 0.\\
\end{array}
\end{equation}

Then,  denoting $K:=\ker\beta$,  the middle cohomology $\mc{E}:= K/\func{img} \alpha$ is always a stable bundle with
        \begin{displaymath}
                \func{rank}(\mc{E})=2,\quad c_1(\mc{E})=0, 
                \quad c_2(\mc{E})=c\cdot h^2
        \end{displaymath} 
where  $h:= c_1(\mathcal{O}_X(1))$ is the hyperplane class and $c\geq1$ is an integer.

conclusions:
\int_{X}
        \Phi \wedge dd^{c}f\wedge \Omega 
        =\int_{X}
        f.\left( -\mathbf{i}\bar{\partial}\partial \Phi \right) \wedge \Omega         +\mathbf{i}\int_{\partial X}
        \left( \Phi \wedge \bar{\partial}f+f.\partial \Phi \right)\wedge\Omega.

nodes.statement:
The curvature on a K\"{a}hler $n-$fold splits as $F=\hat{F}.\omega \oplus
F^{\perp }\in \Omega ^{1,1}\left( \func{End}\mathcal{E}\right) $, so: 
\begin{equation*}
F^{2}\wedge \omega ^{n-2}=\hat{F}^{2}.\omega ^{n}+( F^{\perp })
^{2}\wedge \omega ^{n-2}.
\end{equation*}

The Hodge-Riemann pairing $\left( \alpha ,\beta \right) \longmapsto \alpha
\wedge \beta \wedge \omega^{n-2} $ on $\Omega ^{1,1}\left( W\right) $ is
positive-definite along $\omega $ and negative-definite on the primitive
forms in $\left\langle \omega \right\rangle ^{\perp }$ \cite[pp.39-40]
{Huybrechts} (with respect to the reference Hermitian bundle metric); since
the curvature $F$ is real as a bundle-valued $2-$form, we have:
\begin{equation} \func{tr}F^{2}\wedge \omega ^{n-2}
        =\left( \vert F^{\perp}\vert ^{2}
        -\vert \hat{F}\vert ^{2}\right) \omega ^{n}
\end{equation}
using that $\func{tr}\xi ^{2}=-\left\vert \xi \right\vert ^{2}$ on the
Lie algebra part.

conclusions:
\func{tr}F^{2}\wedge \omega ^{n-2}
        =\left( \vert F^{\perp}\vert ^{2}
        -\vert \hat{F}\vert ^{2}\right) \omega ^{n}
